Deno.test("SecurityService.getSecurityToken", async t => {
	let token: string = "";
	await t.step({
		name: "Register account",
		fn: async _ => {
			const accountService = new AccountService();
			const account = await accountService.registerAnonymous();
			token = account.value;
		}
	});
	assertNotEquals(token, "", "Account token should not be empty");
	console.log((await new SecurityService().getSecurityToken(token)));
});
